WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_prices) AS element FROM price_tiers) SELECT CASE WHEN element >= 64 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, SIZE(COLLECT_SET(currency)) AS num_currencies, SUM(element) FILTER (WHERE currency = 'EUR') AS eur_total_element FROM lines GROUP BY CASE WHEN element >= 64 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY eur_total_element DESC;
